// আপনার যে লিঙ্কে রিডাইরেক্ট করতে চান
const REDIRECT_URL = 'https://c.tenor.com/j3MVp-l8upYAAAAC/tenor.gif';

function checkDevTools() {
  // DevTools ডক করা থাকলে Outer size, Inner size-এর চেয়ে বড় হবে
  const isDevToolsOpen =
    window.outerHeight - window.innerHeight > 150 || // উচ্চতার পার্থক্য
    window.outerWidth - window.innerWidth > 200; // প্রস্থের পার্থক্য

  if (isDevToolsOpen) {
    // যদি DevTools খোলা থাকে, তবে সরাসরি রিডাইরেক্ট করুন
    // replace() ব্যবহার করলে ব্রাউজার হিস্টোরিতে আগের পেজটি থাকবে না
    window.location.replace(REDIRECT_URL);
  }
}

// ১. উইন্ডোর আকারের পরিবর্তন মনিটর করুন (যখন কেউ DevTools খোলে বা বন্ধ করে)
window.addEventListener('resize', checkDevTools);

// ২. পেজ লোডের সময় বারবার চেক করার জন্য একটি ফাস্ট ইন্টারভাল ব্যবহার করুন
// (যেমন প্রতি 50 মিলিসেকেন্ডে)
setInterval(checkDevTools, 1000);

// ৩. পেজ লোডের সময় একবার চেক করুন
checkDevTools();

