// আপনার যে লিঙ্কে রিডাইরেক্ট করতে চান (DevTools খোলা হলে)

// =======================================================
// কাস্টম মেনুর জন্য HTML উপাদান তৈরি (DOM Element Creation)
// =======================================================

const menu = document.createElement('div');
menu.id = 'custom-context-menu';
menu.style.cssText = `
    display: none;
    position: absolute;
    z-index: 9999;
    background-color: #fff;
    border: 1px solid #ccc;
    box-shadow: 2px 2px 5px rgba(0, 0, 0, 0.2);
    padding: 2px;
    min-width: 120px;
    border-radius: 4px;
`;

const reloadButton = document.createElement('button');
reloadButton.textContent = 'Reload 🔄';
reloadButton.style.cssText = `
    width: 100%;
    padding: 6px 10px;
    text-align: left;
    background: none;
    border: none;
    cursor: pointer;
    font-size: 14px;
    color: #333;
`;

// হোভার ইফেক্ট যোগ করা
reloadButton.onmouseover = function () {
  this.style.backgroundColor = '#f0f0f0';
};
reloadButton.onmouseout = function () {
  this.style.backgroundColor = 'none';
};

menu.appendChild(reloadButton);
document.body.appendChild(menu); // মেনুটি বডিতে যোগ করা হলো

// =======================================================
// ফাংশন এবং ইভেন্ট লিসেনার সেটআপ
// =======================================================

function hideContextMenu() {
  menu.style.display = 'none';
}

// ১. রাইট-ক্লিক ব্লক এবং কাস্টম মেনু দেখানো
document.addEventListener('contextmenu', function (e) {
  e.preventDefault(); // ব্রাউজারের ডিফল্ট মেনু ব্লক করা

  // মাউসের অবস্থানে মেনু সেট করা
  menu.style.top = e.clientY + 'px';
  menu.style.left = e.clientX + 'px';
  menu.style.display = 'block';
});

// ২. মেনুর বাইরে ক্লিক করলে মেনু লুকানো
document.addEventListener('click', hideContextMenu);

// ৩. 'Reload' বাটনে ক্লিক করলে পেজ রিফ্রেশ করা
reloadButton.addEventListener('click', function () {
  window.location.reload(); // পেজ রিফ্রেশ
  hideContextMenu();
});

// =======================================================
// DevTools ডিটেকশন এবং রিডাইরেক্ট
// =======================================================

function checkDevTools() {
  // উইন্ডোর আকারের পার্থক্য দিয়ে DevTools খোলা কিনা তা দ্রুত চেক করা
  const isDevToolsOpen =
    window.outerHeight - window.innerHeight > 150 ||
    window.outerWidth - window.innerWidth > 200;

  if (isDevToolsOpen) {
    // কোনো দেরি না করে সরাসরি রিডাইরেক্ট
    window.location.replace(REDIRECT_URL);
  }
}

// উইন্ডোর আকারের পরিবর্তন মনিটর করা
window.addEventListener('resize', checkDevTools);

// দ্রুত এবং ঘন ঘন চেক করার জন্য ইন্টারভাল সেট করা
setInterval(checkDevTools, 50);

// পেজ লোডের সময় একবার চেক করা
checkDevTools();
